import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class ConfigService {
    private static final ConcurrentHashMap<String, String> configCache = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config/import", new ConfigImportHandler());
        server.createContext("/api/config/get", new ConfigGetHandler());
        server.setExecutor(Executors.newFixedThreadPool(4));
        server.start();
        System.out.println("ConfigService started on port 8080");
    }

    static class ConfigImportHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }

            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("application/xml")) {
                exchange.sendResponseHeaders(415, 0);
                exchange.close();
                return;
            }

            // Validate auth token presence
            String authToken = exchange.getRequestHeaders().getFirst("X-Service-Token");
            if (authToken == null || authToken.length() < 32) {
                exchange.sendResponseHeaders(401, 0);
                exchange.close();
                return;
            }

            try {
                InputStream body = exchange.getRequestBody();
                SAXParserFactory factory = SAXParserFactory.newInstance();
                // Disable DTD loading for security
                factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
                factory.setFeature("http://xml.org/sax/features/external-general-entities", true);
                factory.setFeature("http://xml.org/sax/features/external-parameter-entities", true);
                factory.setValidating(false);

                SAXParser parser = factory.newSAXParser();
                ConfigXMLHandler handler = new ConfigXMLHandler();
                parser.parse(body, handler);

                // Store parsed config entries
                handler.getEntries().forEach(configCache::put);

                String response = "{\"status\":\"imported\",\"count\":" + handler.getEntries().size() + "}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, response.length());
                exchange.getResponseBody().write(response.getBytes());
                exchange.close();
            } catch (Exception e) {
                String error = "{\"error\":\"" + e.getMessage().replace("\"", "\\\"") + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(400, error.length());
                exchange.getResponseBody().write(error.getBytes());
                exchange.close();
            }
        }
    }

    static class ConfigGetHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            String query = exchange.getRequestURI().getQuery();
            String key = query != null && query.startsWith("key=") ? query.substring(4) : null;
            if (key == null) {
                exchange.sendResponseHeaders(400, 0);
                exchange.close();
                return;
            }
            String value = configCache.getOrDefault(URLDecoder.decode(key, "UTF-8"), "");
            exchange.getResponseHeaders().set("Content-Type", "text/plain");
            exchange.sendResponseHeaders(200, value.length());
            exchange.getResponseBody().write(value.getBytes());
            exchange.close();
        }
    }

    static class ConfigXMLHandler extends DefaultHandler {
        private ConcurrentHashMap<String, String> entries = new ConcurrentHashMap<>();
        private String currentKey = null;
        private StringBuilder currentValue = new StringBuilder();
        private boolean inEntry = false;

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            if ("entry".equals(qName)) {
                currentKey = attrs.getValue("key");
                currentValue = new StringBuilder();
                inEntry = true;
            }
        }

        @Override
        public void characters(char[] ch, int start, int length) {
            if (inEntry) currentValue.append(ch, start, length);
        }

        @Override
        public void endElement(String uri, String localName, String qName) {
            if ("entry".equals(qName) && currentKey != null) {
                entries.put(currentKey, currentValue.toString().trim());
                inEntry = false;
            }
        }

        public ConcurrentHashMap<String, String> getEntries() { return entries; }
    }
}
